async function main(ctx) {
  const input = ctx.input || {};

  const author = String(input.author || '').trim();
  const commentary = String(input.commentary || '').trim();
  if (!author) throw new Error('author is required (urn:li:person:... or urn:li:organization:...)');
  if (!author.startsWith('urn:li:')) throw new Error('author must be a LinkedIn URN (urn:li:...). Got: ' + author);
  if (!commentary) throw new Error('commentary is required');

  const imageUrls = Array.isArray(input.imageUrls) ? input.imageUrls : [];
  const attachmentIds = Array.isArray(input.attachmentIds) ? input.attachmentIds : [];

  if (Array.isArray(input.images) && input.images.length > 0) {
    throw new Error('images[] is not supported. Use top-level imageUrls[] or attachmentIds[]');
  }

  if (imageUrls.length > 1 || attachmentIds.length > 1) {
    console.log('Warning: Only the first non-empty image will be used. Multiple images not yet supported.');
  }

  const firstImageUrl = (imageUrls.find((u) => typeof u === 'string' && u.trim()) || '').trim();
  const firstAttachmentId = (attachmentIds.find((a) => typeof a === 'string' && a.trim()) || '').trim();

  if (firstImageUrl && firstAttachmentId) {
    throw new Error('Provide only one of imageUrls or attachmentIds, not both');
  }

  const hasImages = Boolean(firstImageUrl || firstAttachmentId);
  const imageSource = firstAttachmentId ? 'attachment' : (firstImageUrl ? 'url' : null);

  return {
    dryRun: input.dryRun === true,
    hasImages,
    needsAttachmentResolution: imageSource === 'attachment',
    imageSource,
    image: {
      attachmentId: firstAttachmentId,
      imageUrl: firstImageUrl,
      description: typeof input.imageDescription === 'string' ? input.imageDescription : ''
    },
    author,
    commentary,
    visibility: input.visibility || 'PUBLIC',
    article: input.article,
    uploadOwner: typeof input.uploadOwner === 'string' ? input.uploadOwner.trim() : ''
  };
}

async function main(ctx) {
  const data = ctx.lastOutputOf('check_images') || {};
  const author = String(data.author || '').trim();

  return {
    dryRun: true,
    note: 'Dry run: no LinkedIn API calls were made.',
    author,
    commentary: data.commentary,
    visibility: data.visibility,
    article: data.article,
    hasImages: !!data.hasImages,
    imageSource: data.imageSource,
    image: data.image,
    registerUpload: data.hasImages ? {
      owner: author,
      ownerMode: 'author',
      serviceRelationshipIdentifier: 'urn:li:userGeneratedContent',
      recipe: 'urn:li:digitalmediaRecipe:feedshare-image'
    } : null,
    warnings: (String(data.uploadOwner || '').trim())
      ? ['uploadOwner was provided but will be ignored to satisfy LinkedIn content ownership rules (media must be owned by the post author).']
      : []
  };
}

