async function main(ctx) {
  const resp = ctx.lastOutputOf('fetch_preview_urls') || {};
  const resolveData = ctx.lastOutputOf('resolve_attachments') || {};
  const originalData = resolveData.originalData || {};
  const attachmentId = String(((originalData.image || {}).attachmentId) || '').trim();

  const body = resp.body ?? resp;
  const data = (body && body.data !== undefined) ? body.data : body;

  const isObj = (v) => v && typeof v === 'object';

  const pickUrlFromObj = (obj) => {
    if (!isObj(obj)) return '';
    const direct = obj.previewUrl || obj.preview_url || obj.downloadUrl || obj.download_url || obj.url;
    if (typeof direct === 'string' && direct.startsWith('http')) return direct;
    if (isObj(obj.preview)) {
      const u = pickUrlFromObj(obj.preview);
      if (u) return u;
    }
    if (isObj(obj.urls)) {
      const u = pickUrlFromObj(obj.urls);
      if (u) return u;
    }
    return '';
  };

  if (attachmentId && isObj(data) && data[attachmentId]) {
    const u = pickUrlFromObj(data[attachmentId]);
    if (u) return { url: String(u), originalData };
  }

  if (Array.isArray(data)) {
    const first = data[0];
    const u = pickUrlFromObj(first);
    if (u) return { url: String(u), originalData };
  }

  if (isObj(data)) {
    if (Array.isArray(data.attachments) && data.attachments[0]) {
      const u = pickUrlFromObj(data.attachments[0]);
      if (u) return { url: String(u), originalData };
    }
    if (Array.isArray(data.items) && data.items[0]) {
      const u = pickUrlFromObj(data.items[0]);
      if (u) return { url: String(u), originalData };
    }
  }

  const urls = [];
  const seen = new Set();
  const walk = (v) => {
    if (v === null || v === undefined) return;
    if (typeof v === 'string') {
      if (v.startsWith('http://') || v.startsWith('https://')) urls.push(v);
      return;
    }
    if (!isObj(v)) return;
    if (seen.has(v)) return;
    seen.add(v);
    if (Array.isArray(v)) {
      for (const it of v) walk(it);
      return;
    }
    for (const k of Object.keys(v)) {
      walk(v[k]);
    }
  };
  walk(data);

  const previewish = urls.find((u) => u.includes('preview')) || urls[0] || '';
  if (previewish) return { url: String(previewish), originalData };

  let topKeys = [];
  try {
    if (isObj(data) && !Array.isArray(data)) topKeys = Object.keys(data).slice(0, 30);
  } catch (_) {}

  throw new Error('Could not extract preview URL from attachment response. attachmentId=' + attachmentId + ' keys=' + JSON.stringify(topKeys));
}

