async function main(ctx) {
  const data = ctx.lastOutputOf('check_images') || {};

  const author = String(data.author || '').trim();
  if (!author) throw new Error('Missing author');
  if (!author.startsWith('urn:li:')) {
    throw new Error('author must be a LinkedIn URN (urn:li:...). Got: ' + author);
  }

  // IMPORTANT: LinkedIn requires that media content used in a post is owned by the post author.
  // We therefore register uploads under the same URN as `author`.
  // `uploadOwner` is retained for backward compatibility but is intentionally ignored.
  const uploadOwner = String(data.uploadOwner || '').trim();
  if (uploadOwner) {
    if (!uploadOwner.startsWith('urn:li:')) {
      throw new Error('uploadOwner must be a LinkedIn URN (urn:li:...). Got: ' + uploadOwner);
    }
    console.log('Note: uploadOwner was provided but is ignored to satisfy LinkedIn content ownership rules.');
  }

  const owner = author;

  return {
    owner,
    serviceRelationshipIdentifier: 'urn:li:userGeneratedContent',
    author,
    commentary: data.commentary,
    visibility: data.visibility,
    article: data.article,
    description: (data.image || {}).description || ''
  };
}

async function main(ctx) {
  const registerResp = ctx.lastOutputOf('publish_text') || {};
  const prepData = ctx.lastOutputOf('prepare_register') || {};
  const body = registerResp.body || registerResp;

  if (!body || !body.value) {
    throw new Error('Invalid image initialization response - no value field');
  }

  const uploadUrl = body.value.uploadUrl;
  const imageUrn = body.value.image;

  if (!imageUrn || !uploadUrl) {
    throw new Error('Missing image URN or uploadUrl from initialization');
  }

  return {
    asset: imageUrn,
    uploadUrl,
    uploadHeaders: {},
    description: prepData.description || '',
    author: prepData.author,
    commentary: prepData.commentary,
    visibility: prepData.visibility,
    article: prepData.article
  };
}

