async function main(ctx) {
  const uploadResp = ctx.lastOutputOf('upload_binary') || {};
  const extractData = ctx.lastOutputOf('extract_upload_url') || {};

  if (uploadResp.status < 200 || uploadResp.status >= 300) {
    throw new Error('Binary upload failed: ' + uploadResp.status);
  }

  const author = String(extractData.author || '').trim();
  const assetUrn = String(extractData.asset || '').trim();
  if (!author) throw new Error('Missing author');
  if (!assetUrn) throw new Error('Missing asset URN from registerUpload');

  return {
    author,
    commentary: extractData.commentary,
    visibility: extractData.visibility || 'PUBLIC',
    attachmentIds: [assetUrn]
  };
}

async function main(ctx) {
  const data = ctx.lastOutputOf('check_images') || {};

  const author = String(data.author || '').trim();
  const payload = {
    author,
    commentary: data.commentary,
    visibility: data.visibility
  };

  const isOrg = author.startsWith('urn:li:organization:');
  if (!isOrg && data.article) {
    payload.content = { article: data.article };
  }

  return payload;
}

async function main(ctx) {
  const resp = ctx.lastOutputOf('publish_with_image') || ctx.lastOutputOf('publish_text') || {};
  const headers = resp.headers || {};

  const postUrn = headers['x-restli-id'] || headers['x-restli_id'] || headers['X-Restli-Id'] || headers['X-Restli-ID'];

  return {
    postUrn: postUrn ? String(postUrn) : '',
    response: resp
  };
}
